#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x < y) - (x > y);
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *p = (int *)malloc(N * sizeof(int));
    if (p == NULL) return 0;

    for (int i = 0; i < N; i++) {
        scanf("%d", &p[i]);
    }

    qsort(p, N, sizeof(int), cmp);

    long long total = 0;
    for (int i = 0; i < N; i++) {
        if ((i + 1) % 3 != 0) {
            total += p[i];
        }
    }

    printf("%lld\n", total);

    free(p);
    return 0;
}
